package com.primehr.security;
import com.primehr.integration.administrative.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Component;
@Component public class RspScreeningPolicyPermissionGuard {public static final String FEATURE="primehr.rsp-screening-policy";private final AdministrativeAuthorizationClient client;public RspScreeningPolicyPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public EffectiveFeaturePermission require(PrimeHrAction action,String token){if(token==null||!token.regionMatches(true,0,"Bearer ",0,7))throw new AccessDeniedException("A bearer token is required");EffectiveFeaturePermission p=client.resolve(FEATURE,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case PUBLISH->p.canPublish();default->false;};if(!allowed||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("RSP screening policy requires agency-wide permission");return p;}}
